from rich.repr import auto

class CustomEq:
    def __init__(self, val=None):
        self.val = val
    def __eq__(self, other):
        return True

# To simulate the BUG, we would have used '=='
# If we had used '==', then param.default == param.empty would be True
# because CustomEq.__eq__ returns True.
# Then it would yield getattr(self, param.name), which is just the value.

